import React, { useState, useEffect } from 'react';
import Calendar from 'react-calendar';
import { tasksAPI, goalsAPI } from '../utils/api';
import { Calendar as CalendarIcon, CheckSquare, Target, Plus, Edit, Trash2, StickyNote } from 'lucide-react';
import toast from 'react-hot-toast';
import 'react-calendar/dist/Calendar.css';

const CalendarPage = () => {
  const [date, setDate] = useState(new Date());
  const [tasks, setTasks] = useState([]);
  const [goals, setGoals] = useState([]);
  const [selectedDateEvents, setSelectedDateEvents] = useState([]);
  const [notes, setNotes] = useState([]);
  const [selectedDateNotes, setSelectedDateNotes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showNoteModal, setShowNoteModal] = useState(false);
  const [editingNote, setEditingNote] = useState(null);
  const [noteFormData, setNoteFormData] = useState({
    title: '',
    content: '',
    date: ''
  });

  useEffect(() => {
    fetchData();
  }, []);

  useEffect(() => {
    filterEventsByDate(date);
  }, [date, tasks, goals, notes]);

  const fetchData = async () => {
    try {
      const [tasksRes, goalsRes] = await Promise.all([
        tasksAPI.getAll(),
        goalsAPI.getAll()
      ]);
      setTasks(tasksRes.data);
      setGoals(goalsRes.data);

      // Load notes from localStorage
      const savedNotes = JSON.parse(localStorage.getItem('calendar-notes') || '[]');
      setNotes(savedNotes);
    } catch (error) {
      // Demo mode
      const savedTasks = JSON.parse(localStorage.getItem('tasks') || '[]');
      const savedGoals = JSON.parse(localStorage.getItem('goals') || '[]');
      const savedNotes = JSON.parse(localStorage.getItem('calendar-notes') || '[]');
      setTasks(savedTasks);
      setGoals(savedGoals);
      setNotes(savedNotes);
    } finally {
      setLoading(false);
    }
  };

  const filterEventsByDate = (selectedDate) => {
    const dateStr = selectedDate.toDateString();

    const dayTasks = tasks.filter(task => 
      new Date(task.dueDate).toDateString() === dateStr
    );

    const dayGoals = goals.filter(goal => 
      new Date(goal.deadline).toDateString() === dateStr
    );

    const dayNotes = notes.filter(note => 
      new Date(note.date).toDateString() === dateStr
    );

    setSelectedDateEvents([
      ...dayTasks.map(task => ({ ...task, type: 'task' })),
      ...dayGoals.map(goal => ({ ...goal, type: 'goal' }))
    ]);

    setSelectedDateNotes(dayNotes);
  };

  const handleNoteSubmit = (e) => {
    e.preventDefault();
    const savedNotes = JSON.parse(localStorage.getItem('calendar-notes') || '[]');

    if (editingNote) {
      const updatedNotes = savedNotes.map(note => 
        note.id === editingNote.id ? { ...noteFormData, id: editingNote.id } : note
      );
      localStorage.setItem('calendar-notes', JSON.stringify(updatedNotes));
      setNotes(updatedNotes);
      toast.success('Note updated successfully');
    } else {
      const newNote = {
        ...noteFormData,
        id: Date.now().toString(),
        createdAt: new Date().toISOString()
      };
      savedNotes.push(newNote);
      localStorage.setItem('calendar-notes', JSON.stringify(savedNotes));
      setNotes(savedNotes);
      toast.success('Note added successfully');
    }

    setShowNoteModal(false);
    setEditingNote(null);
    setNoteFormData({ title: '', content: '', date: '' });
  };

  const handleEditNote = (note) => {
    setEditingNote(note);
    setNoteFormData({
      title: note.title,
      content: note.content,
      date: note.date
    });
    setShowNoteModal(true);
  };

  const handleDeleteNote = (noteId) => {
    if (window.confirm('Are you sure you want to delete this note?')) {
      const savedNotes = JSON.parse(localStorage.getItem('calendar-notes') || '[]');
      const updatedNotes = savedNotes.filter(note => note.id !== noteId);
      localStorage.setItem('calendar-notes', JSON.stringify(updatedNotes));
      setNotes(updatedNotes);
      toast.success('Note deleted successfully');
    }
  };

  const tileContent = ({ date, view }) => {
    if (view === 'month') {
      const dateStr = date.toDateString();
      const dayTasks = tasks.filter(task => 
        new Date(task.dueDate).toDateString() === dateStr
      );
      const dayGoals = goals.filter(goal => 
        new Date(goal.deadline).toDateString() === dateStr
      );
      const dayNotes = notes.filter(note => 
        new Date(note.date).toDateString() === dateStr
      );

      const totalEvents = dayTasks.length + dayGoals.length + dayNotes.length;

      if (totalEvents > 0) {
        return (
          <div className="flex justify-center space-x-1">
            {dayTasks.length > 0 && <div className="w-1.5 h-1.5 bg-blue-500 rounded-full"></div>}
            {dayGoals.length > 0 && <div className="w-1.5 h-1.5 bg-green-500 rounded-full"></div>}
            {dayNotes.length > 0 && <div className="w-1.5 h-1.5 bg-yellow-500 rounded-full"></div>}
          </div>
        );
      }
    }
    return null;
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="animate-spin rounded-full h-32 w-32 border-b-2 border-primary-600"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 via-indigo-50 to-purple-50 ml-64 pt-16">
      <div className="max-w-7xl mx-auto py-8 px-4 sm:px-6 lg:px-8">
        <div className="text-center mb-12">
          <h1 className="text-4xl md:text-5xl font-bold text-gray-800 mb-4">
            Calendar
            <span className="bg-gradient-to-r from-blue-600 to-purple-600 bg-clip-text text-transparent"> & Notes</span>
          </h1>
          <p className="text-xl text-gray-600 mb-8">
            Organize your schedule and capture important notes
          </p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Calendar */}
          <div className="lg:col-span-2">
            <div className="bg-white rounded-3xl border-2 border-gray-100 shadow-lg p-8">
              <Calendar
                onChange={setDate}
                value={date}
                tileContent={tileContent}
                className="w-full border-none calendar-large"
              />
            </div>
          </div>

          {/* Events and Notes for Selected Date */}
          <div className="lg:col-span-1 space-y-6">
            {/* Notes Section */}
            <div className="bg-white rounded-3xl border-2 border-gray-100 shadow-lg p-6">
              <div className="flex items-center justify-between mb-6">
                <h2 className="text-xl font-bold text-gray-800 flex items-center">
                  <StickyNote className="w-5 h-5 mr-2 text-yellow-500" />
                  Notes for {date.toLocaleDateString()}
                </h2>
                <button
                  onClick={() => {
                    setNoteFormData({ title: '', content: '', date: date.toISOString().split('T')[0] });
                    setShowNoteModal(true);
                  }}
                  className="p-2 bg-gradient-to-r from-blue-600 to-purple-600 text-white rounded-xl hover:from-blue-700 hover:to-purple-700 transition-all duration-300 shadow-lg"
                >
                  <Plus className="w-4 h-4" />
                </button>
              </div>

              {selectedDateNotes.length > 0 ? (
                <div className="space-y-3">
                  {selectedDateNotes.map((note) => (
                    <div key={note.id} className="p-4 bg-yellow-50 border border-yellow-200 rounded-xl">
                      <div className="flex items-start justify-between">
                        <div className="flex-1">
                          <h3 className="font-semibold text-gray-800 mb-2">{note.title}</h3>
                          <p className="text-gray-600 text-sm">{note.content}</p>
                        </div>
                        <div className="flex space-x-1 ml-2">
                          <button
                            onClick={() => handleEditNote(note)}
                            className="p-1 text-gray-400 hover:text-blue-600 transition-colors"
                          >
                            <Edit className="w-4 h-4" />
                          </button>
                          <button
                            onClick={() => handleDeleteNote(note.id)}
                            className="p-1 text-gray-400 hover:text-red-600 transition-colors"
                          >
                            <Trash2 className="w-4 h-4" />
                          </button>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="text-center py-6">
                  <StickyNote className="w-8 h-8 text-gray-400 mx-auto mb-2" />
                  <p className="text-gray-500 text-sm">No notes for this date</p>
                </div>
              )}
            </div>

            {/* Events Section */}
            <div className="bg-white rounded-3xl border-2 border-gray-100 shadow-lg p-6">
              <h2 className="text-xl font-bold text-gray-800 mb-6 flex items-center">
                <CalendarIcon className="w-5 h-5 mr-2 text-blue-500" />
                Events for {date.toLocaleDateString()}
              </h2>

              {selectedDateEvents.length > 0 ? (
                <div className="space-y-3">
                  {selectedDateEvents.map((event) => (
                    <div
                      key={`${event.type}-${event._id}`}
                      className="p-3 border border-gray-200 dark:border-gray-700 rounded-lg"
                    >
                      <div className="flex items-start">
                        {event.type === 'task' ? (
                          <CheckSquare className="w-5 h-5 text-blue-500 mr-2 mt-0.5" />
                        ) : (
                          <Target className="w-5 h-5 text-green-500 mr-2 mt-0.5" />
                        )}
                        <div className="flex-1">
                          <h3 className="font-medium text-gray-900 dark:text-white">
                            {event.title}
                          </h3>
                          {event.description && (
                            <p className="text-sm text-gray-600 dark:text-gray-400 mt-1">
                              {event.description}
                            </p>
                          )}
                          <div className="flex items-center mt-2">
                            <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                              event.type === 'task' 
                                ? 'bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200'
                                : 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200'
                            }`}>
                              {event.type === 'task' ? 'Task' : 'Goal'}
                            </span>
                            {event.type === 'task' && (
                              <span className={`ml-2 px-2 py-1 rounded-full text-xs font-medium ${
                                event.priority === 'high' ? 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200' :
                                event.priority === 'medium' ? 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-200' :
                                'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200'
                              }`}>
                                {event.priority}
                              </span>
                            )}
                            {event.type === 'goal' && (
                              <span className="ml-2 text-xs text-gray-600 dark:text-gray-400">
                                {event.progress}% complete
                              </span>
                            )}
                          </div>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="text-center py-8">
                  <CalendarIcon className="w-12 h-12 text-gray-400 mx-auto mb-4" />
                  <p className="text-gray-600 dark:text-gray-400">
                    No events scheduled for this date
                  </p>
                </div>
              )}
            </div>

            {/* Quick Stats */}
            <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6 mt-6">
              <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
                This Month
              </h3>
              <div className="space-y-3">
                <div className="flex justify-between items-center">
                  <span className="text-gray-600 dark:text-gray-400">Total Tasks</span>
                  <span className="font-semibold text-gray-900 dark:text-white">
                    {tasks.filter(task => 
                      new Date(task.dueDate).getMonth() === date.getMonth() &&
                      new Date(task.dueDate).getFullYear() === date.getFullYear()
                    ).length}
                  </span>
                </div>
                <div className="flex justify-between items-center">
                  <span className="text-gray-600 dark:text-gray-400">Total Goals</span>
                  <span className="font-semibold text-gray-900 dark:text-white">
                    {goals.filter(goal => 
                      new Date(goal.deadline).getMonth() === date.getMonth() &&
                      new Date(goal.deadline).getFullYear() === date.getFullYear()
                    ).length}
                  </span>
                </div>
                <div className="flex justify-between items-center">
                  <span className="text-gray-600 dark:text-gray-400">Completed Tasks</span>
                  <span className="font-semibold text-gray-900 dark:text-white">
                    {tasks.filter(task => 
                      task.status === 'completed' &&
                      new Date(task.dueDate).getMonth() === date.getMonth() &&
                      new Date(task.dueDate).getFullYear() === date.getFullYear()
                    ).length}
                  </span>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default CalendarPage;
